// Shared contracts for the offline app. Owned by the coordinator; agents do not edit this file.

/** Calendar day in Europe/Istanbul, "YYYY-MM-DD". */
export type LocalDate = string;

/** Per-100 g (or per-portion) values. null = no data; never treat null as 0 in UI. */
export type Nutrients = {
  kcal: number | null;
  protein: number | null;
  carbs: number | null;
  fat: number | null;
};

export type Portion = {
  id: string;
  nameTr: string;
  nameEn: string | null;
  grams: number;
};

export type CatalogItemKind = "dish" | "food" | "packaged";

/** One record of the bundled catalog (mobile/assets/catalog.json, generated from catalog/dist). */
export type CatalogItem = {
  id: string;
  kind: CatalogItemKind;
  category: string;
  nameTr: string;
  nameEn: string | null;
  aliases: string[];
  per100g: Nutrients;
  portions: Portion[];
  brand?: string | null;
  quantity?: string | null;
  source: Record<string, unknown>;
};

/** A food the user created on this device. id: "custom-<random>". */
export type CustomFood = {
  id: string;
  nameTr: string;
  per100g: Nutrients;
  portions: Portion[];
  createdAt: string;
  updatedAt: string;
};

export type FoodRef = { kind: CatalogItemKind | "custom"; id: string };

export type MealSlot = "breakfast" | "lunch" | "dinner" | "snack";
export const MEAL_SLOTS: readonly MealSlot[] = ["breakfast", "lunch", "dinner", "snack"];

/** Portion used when the entry was logged; kept as a snapshot. */
export type PortionSnapshot = { id: string; name: string; gramsPerUnit: number; quantity: number };

/**
 * A logged food. Name and per-100 g values are snapshots taken at logging time,
 * so later catalog updates or custom-food edits never change history.
 */
export type DiaryEntry = {
  id: string;
  date: LocalDate;
  mealSlot: MealSlot;
  food: FoodRef;
  foodName: string;
  grams: number;
  portion: PortionSnapshot | null;
  per100g: Nutrients;
  createdAt: string;
  updatedAt: string;
};

export type NewDiaryEntry = Omit<DiaryEntry, "id" | "createdAt" | "updatedAt">;
export type DiaryEntryPatch = Partial<Pick<DiaryEntry, "date" | "mealSlot" | "grams" | "portion">>;

export type Sex = "female" | "male";
export type ActivityLevel = "sedentary" | "light" | "moderate" | "active" | "very_active";
export type Goal = "lose" | "maintain" | "gain";

export type Profile = {
  birthYear: number;
  sex: Sex;
  heightCm: number;
  weightKg: number;
  activity: ActivityLevel;
  goal: Goal;
  /** User overrides; null = use calculated value. */
  kcalOverride: number | null;
  proteinOverride: number | null;
  createdAt: string;
  updatedAt: string;
};

/** Daily targets in kcal and grams. */
export type Targets = { kcal: number; protein: number; carbs: number; fat: number };

/** Total water for a day. */
export type WaterLog = { date: LocalDate; ml: number };

export type WeightLog = { id: string; date: LocalDate; kg: number; createdAt: string };

export type Language = "tr" | "en";

export type Reminder = {
  id: string;
  kind: "meal" | "water";
  mealSlot: MealSlot | null;
  hour: number;
  minute: number;
  enabled: boolean;
};

export type Settings = {
  /** null = follow device language (Turkish unless the device is English). */
  language: Language | null;
  waterGoalMl: number;
  reminders: Reminder[];
};

export const BACKUP_SCHEMA_VERSION = 1;

/** File written by "Yedekle" and read by "Geri yükle". */
export type BackupFile = {
  app: "bite-routine";
  schemaVersion: number;
  exportedAt: string;
  profile: Profile | null;
  settings: Settings;
  diaryEntries: DiaryEntry[];
  customFoods: CustomFood[];
  favorites: FoodRef[];
  waterLogs: WaterLog[];
  weightLogs: WeightLog[];
};
